import pandas as pd
df=pd.read_csv('dataset/hospital_compensation_registry.csv').set_index('patient_id')
import collections
inv=collections.defaultdict(list)
for p,r in df.iterrows(): inv[r.emergency_contact_patient_id].append(p)
def desc(p):
    r=df.loc[p]; return f'{p} {r.full_name} [{r.record_date} {r.compensation_reason}]' if isinstance(r.record_date,str) else f'{p} {r.full_name} [no claim]'
for c in ['PAT_265','PAT_033','PAT_006']:
    print('=====',desc(c))
    seen={c}
    frontier=[c]
    for hop in [1,2]:
        nf=[]
        for p in frontier:
            for q,d in [(df.loc[p].emergency_contact_patient_id,'->')]+[(x,'<-') for x in inv[p]]:
                if q in seen: continue
                seen.add(q); nf.append(q)
                print('  '*hop, p, d, desc(q))
        frontier=nf
"
